/**
 * Adapts a bridge entry to the WaSOS message format.
 *
 * Sets msg.metadata = entry.metadata — the two are the same object from here on.
 * files is set empty here — file preparation happens downstream                                                                                                                                 
 * in Wasos file Handling, which populates msg.payload.files                                                                                                                                     
 * with NewFileRequest objects before the JSON POST.                                                                                                                                             
 */ 
const entry = msg.entry;
const source = entry.metadata.source;
const utils = global.get("utils");

msg.metadata = entry.metadata;
msg.payload = {
    content: entry.text,
    callsign: `${utils.build_callsign(source)} ${entry.author}`,
    isLocation: false,
    replyMessageId: null,
    files: []
};

return msg;

const entry  = msg.entry;
const source = entry.metadata.source;
const utils  = global.get("utils");

// Subject is required (1-200 chars). Truncate to keep CIM happy.
const subject = `${utils.build_callsign(source)} ${entry.author}`.slice(0, 200);

// Internal canonical is UTC ms; CIM expects Norwegian local time as "YYYY-MM-DD HH:mm".
// Convert at the boundary via the reciprocal helper.
const reported_date = utils.format_cim_timestamp(entry.timestamp || Date.now());

msg.metadata = entry.metadata;
msg.payload = {
    subject:       subject,
    description:   entry.text || "",
    source:        "Parat Bridge",
    reported_date: reported_date
};

return msg;

/**
 * Adapts a bridge entry to the Rayvn log entry format.
 *
 * Sets msg.metadata = entry.metadata — the two are the same object from here on.
 * File upload is handled downstream in Handle Rayvn files upload,
 * which reads files from metadata.files.items.
 */
const entry = msg.entry;
const source = entry.metadata.source;
const target = entry.metadata.target;
const utils = global.get("utils");

msg.metadata = entry.metadata;
msg.payload = {
    text: `${utils.build_callsign(source)} ${entry.author}:\n\n${entry.text || ""}`,
    keyEvent: false,
    releasedInfo: false,
    loggedByFullName: `${utils.build_callsign(source)} ${entry.author}`,
    labels: (() => {
            const tag_key = source.client_system.toUpperCase();
            const tag = target.client_specific && target.client_specific.tags && target.client_specific.tags[tag_key];
            return tag ? [tag] : [];
        })()};

return msg;
